from typing import List

def parse_music(music_string: str) -> List[int]:
    if not music_string:
        return []

    note_map = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    result = []
    i = 0
    n = len(music_string)

    while i < n:
        if music_string[i] == ' ':
            i += 1
            continue

        if i + 1 < n and music_string[i:i+2] in note_map:
            result.append(note_map[music_string[i:i+2]])
            i += 2
        elif music_string[i] in note_map:
            result.append(note_map[music_string[i]])
            i += 1
        else:
            raise ValueError(f"Invalid note character at position {i}: '{music_string[i]}'")

    return result

