from typing import List
import math

def rescale_to_unit(numbers: List[float]) -> List[float]:
    if len(numbers) < 2:
        return numbers[:]

    min_val = min(numbers)
    max_val = max(numbers)

    if math.isclose(min_val, max_val):
        return [0.0] * len(numbers)

    diff = max_val - min_val
    return [(x - min_val) / diff for x in numbers]

