from typing import List

def factorize(n: int) -> List[int]:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 1:
        return []
    factors = []
    # 处理因子2
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # 处理奇数因子
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2
    # 如果n剩下大于1，则它是一个质因子
    if n > 1:
        factors.append(n)
    return factors

