def is_prime(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    # Miller-Rabin deterministic for 32-bit integers: bases [2, 7, 61]
    def miller_rabin(d, a):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return True
        while d != n - 1:
            x = (x * x) % n
            d *= 2
            if x == n - 1:
                return True
            if x == 1:
                return False
        return False

    d = n - 1
    while d % 2 == 0:
        d //= 2

    for a in [2, 7, 61]:
        if a >= n:
            continue
        if not miller_rabin(d, a):
            return False
    return True

