def numerical_letter_grade(grades):
    if not grades:
        return []

    thresholds = [4.0, 3.7, 3.3, 3.0, 2.7, 2.3, 2.0, 1.7, 1.3, 1.0, 0.7, 0.0]
    letters = ['A+', 'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D+', 'D', 'D-', 'E']

    result = []
    for gpa in grades:
        if not isinstance(gpa, (int, float)) or gpa < 0.0 or gpa > 4.0:
            raise ValueError(f"Invalid GPA value: {gpa}. GPA must be between 0.0 and 4.0.")

        if gpa == 4.0:
            result.append('A+')
        elif gpa == 0.0:
            result.append('E')
        else:
            # binary search for the correct interval
            lo, hi = 0, len(thresholds) - 1
            while lo < hi:
                mid = (lo + hi) // 2
                if gpa > thresholds[mid]:
                    hi = mid
                else:
                    lo = mid + 1
            result.append(letters[lo])

    return result

