import heapq

def minPath(grid, k):
    n = len(grid)
    # 找到每个值对应的坐标
    val_to_pos = {}
    for i in range(n):
        for j in range(n):
            val_to_pos[grid[i][j]] = (i, j)

    if k == 1:
        return [1]

    # 找到值1的位置
    start_i, start_j = val_to_pos[1]

    # 方向数组
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    # 优先队列: (当前路径列表, 当前行, 当前列)
    # 由于路径列表比较是字典序，Python元组比较就是字典序
    # 但为了效率，我们存储路径长度和最后一个值等信息，用堆保证字典序最小扩展
    # 使用堆存储 (路径元组, i, j)
    # 初始从1开始
    heap = []
    heapq.heappush(heap, ((1,), start_i, start_j))

    # visited[l][i][j] 记录长度为l时是否已经访问过(i,j)且路径更优
    # 由于k可能很大，用字典记录每个长度下每个位置的最优路径
    # 但为了剪枝，我们只记录每个长度下每个位置是否已经扩展过更优路径
    # 因为路径字典序比较，如果之前有更小的路径到达同一位置同一长度，则当前路径可以剪枝
    # 使用字典: best[l][(i,j)] = 路径元组
    best = {}

    while heap:
        path, i, j = heapq.heappop(heap)
        l = len(path)

        if l == k:
            return list(path)

        # 剪枝: 如果已经存在更优的相同长度路径到达此位置，跳过
        key = (i, j)
        if l in best and key in best[l]:
            if path > best[l][key]:
                continue
        # 记录当前最优
        if l not in best:
            best[l] = {}
        best[l][key] = path

        # 扩展邻居
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                new_path = path + (grid[ni][nj],)
                heapq.heappush(heap, (new_path, ni, nj))

    # 理论上不会到这里
    return []

