def tri(n):
    if n == 0:
        return [1]
    res = [0] * (n + 1)
    res[0] = 1
    if n >= 1:
        res[1] = 3
    for i in range(2, n + 1):
        if i % 2 == 0:
            res[i] = 1 + i // 2
        else:
            res[i] = res[i - 1] + res[i - 2] + res[i + 1] if i + 1 <= n else 0
    # 对于奇数项，如果 i+1 超出范围，需要特殊处理，但根据定义，n为奇数时依赖n+1，所以n本身应为偶数或通过迭代保证
    # 实际上，上述循环中奇数项依赖尚未计算的i+1，因此需要调整策略：先计算所有偶数项，再计算奇数项
    # 重新实现更稳健的版本：
    res = [0] * (n + 1)
    res[0] = 1
    if n >= 1:
        res[1] = 3
    # 先计算所有偶数项
    for i in range(2, n + 1, 2):
