                    else:
                        # 否则视为小数分隔符
                        x = x.replace(',', '.')
                else:
                    x = x.replace(',', '.')
            return Decimal(x)
        elif isinstance(x, (int, float)):
            return Decimal(str(x))
        else:
            raise TypeError("Unsupported type")

    try:
        da = to_decimal(a)
        db = to_decimal(b)
