def x_or_y(n, x, y):
    if n < 2:
        return y
    # Miller-Rabin deterministic for 32-bit integers
    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1
    for a in [2, 3, 5, 7, 11]:
        if a >= n:
            continue
        x_val = pow(a, d, n)
        if x_val == 1 or x_val == n - 1:
            continue
        for _ in range(s - 1):
            x_val = pow(x_val, 2, n)
            if x_val == n - 1:
                break
        else:
            return y
    return x

