def do_algebra(operator, operand):
    import operator as op

    ops = {
        '+': op.add,
        '-': op.sub,
        '*': op.mul,
        '//': op.floordiv,
        '**': op.pow
    }

    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '//': 2,
        '**': 3
    }

    tokens = []
    tokens.append(str(operand[0]))
    for i in range(len(operator)):
        tokens.append(operator[i])
        tokens.append(str(operand[i + 1]))

    output = []
    stack = []

    for token in tokens:
        if token not in ops:
            output.append(int(token))
        else:
            while stack and stack[-1] != '(' and precedence.get(stack[-1], 0) >= precedence.get(token, 0):
                if token == '**' and stack[-1] == '**':
                    break
                output.append(ops[stack.pop()])
            stack.append(token)

    while stack:
        output.append(ops[stack.pop()])

    eval_stack = []
    for item in output:
        if isinstance(item, int):
            eval_stack.append(item)
        else:
            b = eval_stack.pop()
            a = eval_stack.pop()
            eval_stack.append(item(a, b))

    return eval_stack[0]

