def kth_element(arr, k):
    # 快速选择算法，返回排序后第k小的元素（1-based索引）
    def quick_select(l, r, k_smallest):
        if l == r:
            return arr[l]
        pivot = arr[r]
        i = l
        for j in range(l, r):
            if arr[j] <= pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[r] = arr[r], arr[i]
        if k_smallest == i:
            return arr[i]
        elif k_smallest < i:
            return quick_select(l, i - 1, k_smallest)
        else:
            return quick_select(i + 1, r, k_smallest)
    return quick_select(0, len(arr) - 1, k - 1)

