```python
def eulerian_num(n, m):
    if m >= n or m < 0:
        return 0
    if m == 0:
        return 1
    dp = [[0] * (m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        dp[i][0] = 1
    for i in range(1, n+1):
        for j in range(1, min(i, m)+1):
            dp[i][j] = (i-j) * dp[i-1][j-1] + (j+1) * dp[i-1][j]
    return dp[n][m]
