def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0
    if m == 0:
        return 1
    # 一维动态规划，只保留上一行的数据
    dp = [0] * (m + 1)
    dp[0] = 1  # 对应 n=1 时 A(1,0)=1
    for i in range(2, n + 1):
        # 从后往前更新，避免覆盖
        for j in range(min(i, m), 0, -1):
            dp[j] = (i - j) * dp[j-1] + (j + 1) * dp[j]
        dp[0] = 1  # 每行第一个元素始终为1
    return dp[m]

