def eulerian_num(n: int, m: int) -> int:
    if n < 0 or m < 0 or m > n:
        return 0
    if n == 0 and m == 0:
        return 1
    # 一维动态规划，dp[k] 表示当前 n 下 A(n, k)
    dp = [0] * (n + 1)
    dp[0] = 1  # A(0,0) = 1
    for i in range(1, n + 1):
        # 从大到小更新，避免覆盖
        for j in range(i, -1, -1):
            if j == 0:
                dp[j] = 1
            else:
                dp[j] = (i - j) * dp[j-1] + (j + 1) * dp[j]
    return dp[m]

