def magic_square_test(matrix):
    if not matrix:
        return False
    n = len(matrix)
    # 检查是否为方阵
    for row in matrix:
        if len(row) != n:
            return False
    if n == 0:
        return False

    # 计算目标值（第一行和）
    target = sum(matrix[0])

    # 检查所有行
    for row in matrix:
        if sum(row) != target:
            return False

    # 检查所有列
    for col in range(n):
        col_sum = 0
        for row in range(n):
            col_sum += matrix[row][col]
        if col_sum != target:
            return False

    # 检查主对角线
    diag1 = 0
    for i in range(n):
        diag1 += matrix[i][i]
    if diag1 != target:
        return False

    # 检查副对角线
    diag2 = 0
    for i in range(n):
        diag2 += matrix[i][n-1-i]
    if diag2 != target:
        return False

    # 验证元素是否包含1到n²的所有整数（经典幻方定义）
    flat = []
    for row in matrix:
        flat.extend(row)
    if len(set(flat)) != n * n:
        return False
    for num in range(1, n * n + 1):
        if num not in flat:
            return False

    return True

