def pancake_sort(arr):
    def flip(arr, k):
        # 反转前 k+1 个元素
        left = 0
        right = k
        while left < right:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

    n = len(arr)
    if n < 2:
        return arr

    for size in range(n, 1, -1):
        # 找到未排序部分最大元素的索引
        max_idx = 0
        for i in range(1, size):
            if arr[i] > arr[max_idx]:
                max_idx = i

        # 如果最大元素已经在正确位置，跳过
        if max_idx == size - 1:
            continue

        # 如果最大元素不在头部，先翻转到头部
        if max_idx != 0:
            flip(arr, max_idx)

        # 再翻转到当前未排序部分的末尾
        flip(arr, size - 1)

    return arr

