    if m < 1 or n < 1:
        return 0
    # dp[i][j] 长度为i，最后一个元素为j的合法序列数
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    # 初始化长度为1的情况
    for j in range(1, m + 1):
        dp[1][j] = 1
    # 从长度2开始递推
    for i in range(2, n + 1):
        # 计算前缀和 prefix[j] = sum(dp[i-1][1..j])
        prefix = [0] * (m + 1)
        for j in range(1, m + 1):
            prefix[j] = prefix[j-1] + dp[i-1][j]
        for j in range(1, m + 1):
            dp[i][j] = prefix[j // 2]
    # 最终结果：所有长度为n，最后一个元素为1..m的序列数之和
    return sum(dp[n][j] for j in range(1, m + 1))

