def max_sub_array_sum_repeated(arr, n, k):
    if not arr or k == 0:
        return 0

    # Kadane算法求最大子数组和
    def kadane(a):
        max_ending_here = max_so_far = a[0]
        for x in a[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # 计算最大前缀和（允许空子数组，但全负时取最大元素）
    prefix = 0
    max_prefix = float('-inf')
    for x in arr:
        prefix += x
        if prefix > max_prefix:
            max_prefix = prefix

    # 计算最大后缀和
    suffix = 0
    max_suffix = float('-inf')
    for x in reversed(arr):
        suffix += x
        if suffix > max_suffix:
            max_suffix = suffix

    total = sum(arr)
    max_single = kadane(arr)

    if k == 1:
        return max_single

    # 当所有元素为负时，max_prefix和max_suffix可能为负，但max_single已经是最大值
    # 跨越两个数组的情况
    two_array = max_prefix + max_suffix
    # 跨越三个及以上数组的情况
    if k >= 3:
        multi_array = total * (k - 2) + max_prefix + max_suffix
        return max(max_single, two_array, multi_array)
    else:  # k == 2
        return max(max_single, two_array)

