from collections import defaultdict

def max_aggregate(tuples_list):
    if not tuples_list:
        return ()

    total = defaultdict(int)
    for name, value in tuples_list:
        total[name] += value

    max_name = max(total, key=lambda name: (total[name], -list(dict.fromkeys(name for name, _ in tuples_list)).index(name)))
    # 更简单的实现：直接使用 max 的默认行为，但为了确保第一个出现的最大者，可以按顺序遍历
    # 实际上 max 在键值相等时会保留第一个遇到的，但字典顺序可能不保证输入顺序
    # 因此我们手动遍历
    max_name = None
    max_score = float('-inf')
    seen = {}
    for name, value in tuples_list:
        if name not in seen:
            seen[name] = len(seen)
    for name, score in total.items():
        if score > max_score or (score == max_score and seen[name] < seen.get(max_name, float('inf'))):
            max_score = score
            max_name = name
    return (max_name, max_score)

